<?php require 'config.php';require_login();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$subject=trim($_POST['subject']??'');$body=trim($_POST['message']??'');if($subject&&$body){$stmt=db()->prepare('INSERT INTO tickets(user_id,subject,message) VALUES(?,?,?)');$stmt->bind_param('iss',$_SESSION['user']['id'],$subject,$body);$stmt->execute();$message='Your ticket is in. We will get back to you shortly.';}}page_start('Contact support'); ?><section class="section-space"><div class="container"><div class="row justify-content-center"><div class="col-lg-7"><div class="eyebrow">Support</div><h1 class="display-5">How can we help?</h1><?php if($message): ?><div class="alert alert-success mt-4"><?= e($message) ?></div><?php endif; ?><form method="post" class="bg-white p-4 rounded-3 mt-4"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><div class="form-outline mb-3"><input class="form-control" name="subject" required><label class="form-label">Subject</label></div><div class="form-outline mb-4"><textarea class="form-control" name="message" rows="6" required></textarea><label class="form-label">How can we help?</label></div><button class="btn btn-dark btn-rounded">Send ticket</button></form></div></div></div></section><?php page_end(); ?>